"""A self-contained, deterministic Wrapped-style HTML story."""
import html
import json

from .card import CANVAS_SCRIPT


def render(stats: dict, redact: bool = False) -> str:
    data = json.dumps(stats, sort_keys=True, ensure_ascii=False).replace("</", "<\\/")
    top = stats["top_sites"][:5]
    top_rows = "".join(f'<li><b>{i}</b><span>{html.escape(x["site"])}</span><em>{x["visits"]:,} visits</em></li>' for i,x in enumerate(top,1)) or '<li class="empty">No visits found</li>'
    era_rows = "".join(f'<article><small>{html.escape(e["start_week"])} → {html.escape(e["end_week"])}</small><h3>{html.escape(e["label"])}</h3><p>{e["visits"]:,} visits across {e["weeks"]} weeks</p></article>' for e in stats["eras"][:3]) or '<p class="muted">More history will reveal your eras.</p>'
    queries = "".join(f'<span>{html.escape(q["query"])}</span>' for q in stats["searches"]["after_midnight"][:5]) or '<span>No late-night searches found</span>'
    page = stats["most_revisited_page"]
    notice = '<div class="hint">Your Chromium history covers about 90 days. Add a Google Takeout export for the full year.</div>' if stats["chromium_limited_hint"] else ''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Your {stats['year']} Web, Wrapped</title>
<style>
:root{{--ink:#14091f;--cream:#fff8e7;--pink:#ff3e9d;--violet:#6536e8;--orange:#ff7a18}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:var(--ink);color:white;font-family:Inter,ui-sans-serif,system-ui,sans-serif}}section{{min-height:100vh;padding:8vw;display:flex;flex-direction:column;justify-content:center;position:relative;overflow:hidden}}section>*{{position:relative;z-index:1}}.hero{{background:radial-gradient(circle at 80% 20%,#ff3e9d 0,transparent 32%),linear-gradient(145deg,#4c1d95,#111827)}}.sites{{background:var(--cream);color:var(--ink)}}.era{{background:linear-gradient(130deg,#ef4444,#f97316)}}.night{{background:radial-gradient(circle at 75% 20%,#7c3aed,transparent 25%),#08051d}}.final{{background:linear-gradient(145deg,#db2777,#6d28d9)}}h1,h2{{font-size:clamp(4rem,13vw,11rem);line-height:.82;letter-spacing:-.075em;margin:.12em 0;max-width:1100px}}h2{{font-size:clamp(3rem,10vw,8rem)}}.eyebrow{{font-weight:900;letter-spacing:.18em;text-transform:uppercase}}.lede{{font-size:clamp(1.2rem,2.4vw,2rem);max-width:680px;line-height:1.4}}.giant{{font-size:clamp(7rem,25vw,18rem);font-weight:950;letter-spacing:-.09em;line-height:.8}}.orb{{position:absolute;width:50vw;height:50vw;border:4vw solid rgba(255,255,255,.12);border-radius:50%;right:-15vw;bottom:-25vw;animation:spin 20s linear infinite}}@keyframes spin{{to{{transform:rotate(360deg)}}}}ol{{list-style:none;padding:0;max-width:900px}}li{{display:grid;grid-template-columns:80px 1fr auto;align-items:center;padding:1rem 0;border-bottom:3px solid var(--ink);font-size:clamp(1rem,3vw,2rem)}}li b{{font-size:2.4em}}li em{{font-style:normal;font-size:.65em}}.cards{{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:20px;margin-top:3rem}}article{{padding:2rem;border:2px solid white;border-radius:24px;background:rgba(0,0,0,.12)}}article h3{{font-size:2rem;margin:.4rem 0}}.pills{{display:flex;gap:12px;flex-wrap:wrap;max-width:900px}}.pills span{{padding:12px 18px;background:white;color:#17102c;border-radius:999px;font-weight:800}}button{{align-self:flex-start;border:0;border-radius:999px;background:#fff;color:#4c1d95;padding:18px 28px;font-size:1.1rem;font-weight:900;cursor:pointer;box-shadow:0 8px 0 #fbbf24}}button:active{{transform:translateY(4px);box-shadow:0 4px 0 #fbbf24}}.privacy{{margin-top:2rem;opacity:.8}}.hint{{position:fixed;z-index:10;left:20px;right:20px;bottom:18px;padding:12px 18px;background:#fff;color:#3b0764;border-radius:12px;text-align:center;font-weight:700;box-shadow:0 4px 30px #0005}}.muted{{opacity:.7}}@media(prefers-reduced-motion:reduce){{*{{animation:none!important;scroll-behavior:auto!important}}}}
</style></head><body>
<section class="hero"><div class="orb"></div><p class="eyebrow">Your web, wrapped</p><h1>{stats['year']} was a journey.</h1><p class="lede">A private look back at the links, late nights and rabbit holes that made your year.</p></section>
<section class="era"><p class="eyebrow">You went places</p><div class="giant">{stats['total_visits']:,}</div><h2>visits.</h2><p class="lede">About {stats['estimated_hours']:,} hours across {stats['active_days']} active days. All calculated on your device.</p></section>
<section class="sites"><p class="eyebrow">Your top corners</p><h2>You kept coming back.</h2><ol>{top_rows}</ol></section>
<section class="era"><p class="eyebrow">Every year has chapters</p><h2>Your eras.</h2><div class="cards">{era_rows}</div></section>
<section class="night"><p class="eyebrow">After dark</p><div class="giant">{stats['night_owl_score']}%</div><h2>night owl.</h2><p class="lede">Your searches after midnight:</p><div class="pills">{queries}</div></section>
<section class="sites"><p class="eyebrow">The one you needed</p><h2>{html.escape(page['title'] or page['url'] or 'No single page yet')}</h2><p class="lede">Revisited {page['visits']} times. Your longest daily streak was <b>{stats['longest_streak_days']} days</b>.</p></section>
<section class="final"><p class="eyebrow">That's your {stats['year']}</p><h2>Keep exploring.</h2><p class="lede">Save a portrait card to share the highlights — without sharing your history.</p><button onclick="downloadCard()">Download share card ↓</button><p class="privacy">🔒 Generated locally. No trackers. No network requests. No data leaves this file.</p></section>{notice}
<script>const DATA={data};const REDACT={str(redact).lower()};{CANVAS_SCRIPT}</script></body></html>'''
